def req(t,a,b,label):
    if a not in t: raise SystemExit(f'missing {label}: {a[:80]}')
    return t.replace(a,b)

def social(t,eid,line):
    p=t.find(f'`ending_id`: `{eid}`'); n=t.find('\n## END-',p+1)
    if p<0: raise SystemExit('missing '+eid)
    if n<0:n=len(t)
    s=t.find('- 社會名譽：',p,n); e=t.find('\n',s)
    if s<0: raise SystemExit('missing social '+eid)
    if e<0:e=len(t)
    return t[:s]+line+t[e:]

def prep(t,body):
    marker='\n---\n\n# 1.'
    if marker not in t: raise SystemExit('missing first section marker')
    if '出發前整備' in t: raise SystemExit('prep already exists')
    return t.replace(marker,'\n---\n\n# 0. 出發前整備\n\n'+body.strip()+'\n\n---\n\n# 1.',1)

